// Modules groups the untracked repositories by feature slice, so a slice
// reaches only its own models.
type Modules struct {
	Audit      AuditRepos
	Auth       AuthRepos
	Bots       BotsRepos
	Chats      ChatsRepos
	Computers  ComputersRepos
	Connectors ConnectorsRepos
	Envelopes  EnvelopesRepos
	Learning   LearningRepos
	Models     ModelsRepos
	Policy     PolicyRepos
	Push       PushRepos
	Routines   RoutinesRepos
	Runs       RunsRepos
	Screens    ScreensRepos
	Settings   SettingsRepos
	Skills     SkillsRepos
	Spaces     SpacesRepos
	Teach      TeachRepos
	Usage      UsageRepos
	Vault      VaultRepos
	Web        WebRepos
	Zones      ZonesRepos
}

// TxModules groups the tracked repositories by feature slice. Every set is
// bound to the same transaction.
type TxModules struct {
	Audit      AuditTxRepos
	Auth       AuthTxRepos
	Bots       BotsTxRepos
	Chats      ChatsTxRepos
	Computers  ComputersTxRepos
	Connectors ConnectorsTxRepos
	Envelopes  EnvelopesTxRepos
	Learning   LearningTxRepos
	Models     ModelsTxRepos
	Policy     PolicyTxRepos
	Push       PushTxRepos
	Routines   RoutinesTxRepos
	Runs       RunsTxRepos
	Screens    ScreensTxRepos
	Settings   SettingsTxRepos
	Skills     SkillsTxRepos
	Spaces     SpacesTxRepos
	Teach      TeachTxRepos
	Usage      UsageTxRepos
	Vault      VaultTxRepos
	Web        WebTxRepos
	Zones      ZonesTxRepos
}

// WithTx runs fn inside a transaction and puts that transaction in the
// context it passes to fn. Reach the tracked repositories with db.Tx(ctx).
// A nested call opens a savepoint on the same transaction.
func (db *DB) WithTx(ctx context.Context, fn func(ctx context.Context) error, opts ...drel.TxOption) error {
	return db.Engine.WithTx(ctx, fn, opts...)
}
